package com.kennypvthax.uisuite;
import android.app.*;
import android.content.*;
import android.graphics.Typeface;
import android.os.*;
import android.view.*;
import android.widget.*;
/** Developer component gallery only. No invented application pages/backend. */
final class Gallery extends android.widget.FrameLayout implements AutoCloseable {
 private boolean preview;private Dialog currentDialog;private final AuroraBackground aurora;private final TapFeedback sound;private final android.content.SharedPreferences preferences;
 private final LinearLayout content;private final Typeface font;private final Handler handler=new Handler(Looper.getMainLooper());private final TextView status;
 private final Runnable reset=()->{if(getWindowToken()!=null)announceForAccessibility("Preview complete");};
 Gallery(Context context){super(context);setBackgroundColor(Tokens.BG);preferences=context.getSharedPreferences("kenny-ui-suite",0);sound=new TapFeedback(context);sound.enabled=preferences.getBoolean("sounds",true);aurora=new AuroraBackground(context);aurora.setReduced(preferences.getBoolean("reduced",false));KennyComponents.reducedMotion=aurora.reduced;addView(aurora,new LayoutParams(-1,-1));
  font=Typeface.create("sans-serif",Typeface.NORMAL);ScrollView scroll=new ScrollView(context);scroll.setFillViewport(true);scroll.setClipToPadding(false);addView(scroll,new LayoutParams(-1,-1));content=new LinearLayout(context);content.setOrientation(1);content.setPadding(dp(20),dp(20),dp(20),dp(32));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));
  setOnApplyWindowInsetsListener((v,i)->{setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});
  text(content,"KennyPvtHax",26,Tokens.TEXT);text(content,"CRIMSON AURORA  /  COMPONENT LAB",11,Tokens.SELECTED);space(16);
  LinearLayout nav=new LinearLayout(context);content.addView(nav);Button[] tabs=new Button[2];String[] labels={"Components","Motion"};for(int i=0;i<2;i++){final int at=i;tabs[i]=KennyComponents.button(context,labels[i],()->{sound.play();for(int k=0;k<2;k++){tabs[k].setTextColor(k==at?Tokens.SELECTED:Tokens.SECONDARY);tabs[k].setSelected(k==at);}if(at==1)scroll.smoothScrollTo(0,content.getChildAt(content.getChildCount()-1).getTop());else scroll.smoothScrollTo(0,0);});tabs[i].setTag("navigation");nav.addView(tabs[i],new LinearLayout.LayoutParams(0,dp(48),1));}tabs[0].setTextColor(Tokens.SELECTED);tabs[0].setSelected(true);space(16);
  LinearLayout panel=section("Buttons & interaction");text(panel,"Original crimson geometry, adapted to 48 dp touch targets.",13,Tokens.SECONDARY);
  Button button=KennyComponents.button(context,"Standard button",()->{sound.play();});add(panel,button);Button glow=KennyComponents.button(context,"Illuminated button",()->{sound.play();});glow.setTag("illuminated");glow.setBackground(KennyComponents.surface(context,0xff30141e,0x99ab6273,10));add(panel,glow);
  Button disabled=KennyComponents.button(context,"Disabled button",()->{});disabled.setEnabled(false);disabled.setTextColor(0xff867579);add(panel,disabled);
  Button pressed=KennyComponents.button(context,"Pressed state specimen",()->{});pressed.setTag("pressed");pressed.setBackground(KennyComponents.surface(context,0xff442029,0xffab6273,10));pressed.setClickable(false);pressed.setContentDescription("Non-interactive pressed button visual specimen");add(panel,pressed);
  panel=section("Selection & values");KennyComponents.Check check=new KennyComponents.Check(context,"Circular checkbox");check.setChecked(preferences.getBoolean("demo-check",true));check.setOnClickListener(v->{sound.play();preferences.edit().putBoolean("demo-check",check.isChecked()).apply();});add(panel,check);
  Switch toggle=new Switch(context);toggle.setText("Toggle component");toggle.setTextColor(Tokens.TEXT);toggle.setTextSize(15);toggle.setMinHeight(dp(48));toggle.setThumbTintList(android.content.res.ColorStateList.valueOf(Tokens.FIRE));toggle.setTrackTintList(android.content.res.ColorStateList.valueOf(0xff442029));toggle.setChecked(preferences.getBoolean("demo-toggle",false));toggle.setOnCheckedChangeListener((v,on)->{sound.play();preferences.edit().putBoolean("demo-toggle",on).apply();});add(panel,toggle);
  TextView value=text(panel,"Intensity · "+preferences.getInt("intensity",55)+"%",14,Tokens.SECONDARY);KennyComponents.Slider slider=new KennyComponents.Slider(context);slider.setProgress(preferences.getInt("intensity",55));slider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int p,boolean user){value.setText("Intensity · "+p+"%");if(user)preferences.edit().putInt("intensity",p).apply();}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});add(panel,slider);add(panel,KennyComponents.field(context));
  add(panel,KennyComponents.button(context,"Preview dialog",()->{sound.play();showDialog();}));
  panel=section("Aurora & feedback");text(panel,"Three advected ribbons · forty seeded stars. Touch the background to attract nearby stars.",13,Tokens.SECONDARY);
  KennyComponents.Check reduced=new KennyComponents.Check(context,"Reduced motion");reduced.setChecked(aurora.reduced);reduced.setOnClickListener(v->{sound.play();aurora.setReduced(reduced.isChecked());KennyComponents.reducedMotion=reduced.isChecked();preferences.edit().putBoolean("reduced",reduced.isChecked()).apply();});add(panel,reduced);
  KennyComponents.Check sounds=new KennyComponents.Check(context,"Subtle tap sounds");sounds.setChecked(sound.enabled);sounds.setOnClickListener(v->{sound.enabled=sounds.isChecked();sound.play();preferences.edit().putBoolean("sounds",sound.enabled).apply();});add(panel,sounds);
  status=text(panel,"Component gallery — use the normal app entry for reference-based screens.",12,Tokens.SECONDARY);applyFont(content);
 }
 private void showDialog(){Dialog dialog=new Dialog(getContext());currentDialog=dialog;LinearLayout p=KennyComponents.panel(getContext());p.setBackground(KennyComponents.surface(getContext(),Tokens.ELEVATED,Tokens.OUTLINE,12));text(p,"Crimson glass dialog",20,Tokens.TEXT);text(p,"Local component demonstration. No remote action or feature setting changes.",14,Tokens.SECONDARY);add(p,KennyComponents.button(getContext(),"Close",()->{sound.play();dialog.dismiss();}));dialog.setContentView(p);if(dialog.getWindow()!=null){dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(getWidth()-dp(32),dp(400)),-2);}dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(Math.min(getWidth()-dp(32),dp(400)),-2);applyFont(p);}
 private int dp(float n){return (int)KennyComponents.dp(getContext(),n);}
 private void space(int h){android.view.View v=new android.view.View(getContext());content.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
 private LinearLayout section(String title){LinearLayout p=KennyComponents.panel(getContext());LinearLayout.LayoutParams params=new LinearLayout.LayoutParams(-1,-2);params.bottomMargin=dp(16);content.addView(p,params);text(p,title,17,Tokens.TEXT);View line=new View(getContext());line.setBackgroundColor(0x55665059);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(1));lp.topMargin=dp(10);lp.bottomMargin=dp(12);p.addView(line,lp);return p;}
 private TextView text(LinearLayout parent,String value,int size,int color){TextView t=new TextView(getContext());t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setTypeface(font);t.setPadding(0,dp(3),0,dp(6));parent.addView(t);return t;}
 private void add(LinearLayout p,View v){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);p.addView(v,lp);}
 private void applyFont(View v){if(v instanceof TextView)((TextView)v).setTypeface(font);if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++)applyFont(g.getChildAt(i));}}
 public boolean dispatchTouchEvent(android.view.MotionEvent e){aurora.touch(e.getX()-aurora.getLeft(),e.getY()-aurora.getTop(),e.getActionMasked()!=android.view.MotionEvent.ACTION_UP&&e.getActionMasked()!=android.view.MotionEvent.ACTION_CANCEL);return super.dispatchTouchEvent(e);}
 void freezePreview(float seconds){if(!Float.isFinite(seconds)||seconds<0||seconds>60)return;preview=true;aurora.stop();aurora.model.time=seconds;aurora.model.particleTime=seconds;for(int i=0;i<40;i++){aurora.model.x[i]=AuroraModel.homeX(i,seconds);aurora.model.y[i]=AuroraModel.homeY(i,seconds);}aurora.invalidate();}
 void resume(){if(!preview)aurora.start();}void pause(){if(currentDialog!=null){currentDialog.dismiss();currentDialog=null;}aurora.stop();handler.removeCallbacks(reset);}public void close(){pause();sound.close();}
}
